<script setup lang="ts">
import { KeyRound, Network, Plus, RefreshCw, Trash2 } from '@lucide/vue'
import CenterSupplierDrawer from '@/components/organizations/CenterSupplierDrawer.vue'
import SearchToolbar from '@/components/common/SearchToolbar.vue'
import StatusBadge from '@/components/common/StatusBadge.vue'
import { useCenterSuppliers } from '@/composables/organizations/useCenterSuppliers'

const supplier = useCenterSuppliers()
const licenseName = (value: string) => value === 'internal' ? '内部测试' : '同行代理'
const abilities = (item: Record<string, any>) => [item.allowAgentManagement && '后台账号', item.allowSupplierManagement && '供应商接入', item.allowPlatformSettings && '平台设置', item.allowCustomBrand && '自定义品牌', item.allowCustomApiProviders && '自定义 API'].filter(Boolean)
</script>

<template>
  <section class="management-page supplier-page">
    <header class="page-heading management-heading"><div><span class="eyebrow">Official channel access</span><h1>供应商接入</h1><p>开设下级一级代理，配置项目与构建额度，并签发官方构建中心 Token。</p></div><div class="heading-actions"><button class="secondary-button" :disabled="supplier.loading.value" @click="supplier.load"><RefreshCw :size="16" />刷新</button><button class="primary-button" @click="supplier.openCreate"><Plus :size="17" />新增一级代理</button></div></header>
    <div class="supplier-guidance"><Network :size="20" /><div><strong>这里管理一级代理部署授权</strong><span>内部后台员工请在“后台账号”创建；二级代理由所属一级代理在自己的“组织主体”中创建。</span></div></div>
    <SearchToolbar v-model="supplier.search.value" v-model:field="supplier.searchField.value" :fields="supplier.searchFields" placeholder="输入代理名称或 Supplier ID" :loading="supplier.loading.value" :result-text="`共 ${supplier.rows.value.length} 个一级代理`" @search="supplier.submitSearch" @reset="supplier.resetSearch"><select v-model="supplier.status.value"><option value="all">全部状态</option><option value="enabled">启用</option><option value="disabled">停用</option><option value="expired">已到期</option></select></SearchToolbar>
    <div class="table-panel panel-card"><div class="data-table-scroll"><table class="data-table supplier-table"><thead><tr><th>一级代理</th><th>状态与类型</th><th>授权到期时间</th><th>备注</th><th>额度使用</th><th>授权能力</th><th>最近活动</th><th class="action-column">操作</th></tr></thead><tbody><tr v-for="item in supplier.rows.value" :key="item.id"><td><div class="entity-cell"><span class="entity-avatar"><Network :size="18" /></span><div><strong>{{ item.name }}</strong><span class="mono-text compact">{{ item.id }}</span><small>Token 尾号 {{ item.tokenPreview || '—' }}</small></div></div></td><td><StatusBadge :status="item.authorizationStatus || item.status" /><small class="cell-note">{{ licenseName(item.licenseType) }} · 授权版本 {{ item.authorizationVersion || 1 }}</small></td><td><span class="date-cell">{{ supplier.formatLicenseExpiry(item.expiresAt) }}</span></td><td><span class="supplier-notes" :title="item.notes || ''">{{ item.notes || '—' }}</span></td><td><strong>项目 {{ item.usedProjects || 0 }} / {{ item.maxProjects ? item.maxProjects : '不限' }}</strong><small class="cell-note">{{ item.projectUsageSynced === false ? '项目用量待下游同步' : '项目用量已同步' }}</small><span class="cell-note">构建 {{ item.usedBuilds || 0 }} / {{ item.maxBuilds ? item.maxBuilds : '不限' }}</span></td><td><div class="supplier-ability-tags"><span v-for="ability in abilities(item)" :key="String(ability)" class="soft-tag">{{ ability }}</span><small v-if="!abilities(item).length" class="cell-note">未授权扩展能力</small></div></td><td><span class="date-cell">连接：{{ supplier.formatTime(item.lastSeenAt) }}</span><span class="date-cell">构建：{{ supplier.formatTime(item.lastBuildAt) }}</span></td><td class="action-column"><div class="row-actions"><button class="text-button" @click="supplier.openEdit(item)">编辑</button><button class="text-button" :disabled="supplier.saving.value" @click="supplier.resetToken(item)"><KeyRound :size="13" />重置 Token</button><button class="text-button danger" :disabled="supplier.saving.value" @click="supplier.remove(item)"><Trash2 :size="13" />删除</button></div></td></tr></tbody></table></div><div v-if="supplier.loading.value" class="table-loading">正在加载一级代理…</div><div v-else-if="!supplier.rows.value.length" class="empty-state"><Network :size="34" /><h2>暂无一级代理</h2><p>点击“新增一级代理”签发首个接入凭据。</p></div></div>
    <CenterSupplierDrawer :open="supplier.drawerOpen.value" :form="supplier.form" :saving="supplier.saving.value" :error-message="supplier.errorMessage.value" :reveal-notice="supplier.revealNotice.value" @close="supplier.drawerOpen.value = false" @save="supplier.save" @copy="supplier.copyConfig" />
  </section>
